  function group(paper, id) { return groups[paper+'/'+id]; }
  function get(paper, id, index) {
    const entry = group(paper, id);
    if (!entry || !Number.isInteger(index) || index < 1 || index > entry[3].length) return null;
    const [topic, difficulty, unit, rows] = entry;
    const [prompt, method, value, conclusion] = rows[index-1];
    const numeric = value !== null;
    const solution = method+'。'+conclusion+'。';
    const q = {id, topic, difficulty, prompt, kind:numeric?'number':'text', working:numeric, solution,
      criteria:[{id:'method',max:1,mode:'manual',label:method},{id:'answer',max:1,mode:numeric?'auto':'manual',label:conclusion}],
      sample:{answer:numeric?String(value):solution,working:numeric?method:''},
      source:{type:'original',author:'EduFlow HK',review:'待科任教師審題'}};
    if (numeric) q.expected = value;
    if (unit) q.unit = unit;
    return q;
  }
  globalThis.EduPercentageVariants = Object.freeze({get, count:(paper,id)=>group(paper,id)?.[3].length || 0});
